use std::{fs,process::Command,time::{SystemTime,UNIX_EPOCH},path::Path};
use serde_json::{json,Value};
fn run(p:&Path,args:&[&str])->Value{let o=Command::new(env!("CARGO_BIN_EXE_atlas-native-storage-contract")).arg(args[0]).arg(p).args(&args[1..]).output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));serde_json::from_slice(&o.stdout).unwrap()}
#[test]fn exact_coordinate_roundtrip(){let p=std::env::temp_dir().join(format!("atlas-float-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));run(&p,&["create-workspace"]);let note=run(&p,&["create-note","test","body"]);let id=note["id"].as_str().unwrap();let values=[101.84897331426901_f64,-0.00000000000000012345678912345678_f64,1.0000000000000002_f64,9007199254740990.0_f64];for v in values {let board=json!({"objects":[{"id":id,"x":v,"y":v}],"edges":[],"stacks":[]});run(&p,&["put-board",&board.to_string()]);let saved=run(&p,&["get-board"]);assert_eq!(saved["objects"][0]["x"].as_f64().unwrap().to_bits(),v.to_bits());}fs::remove_dir_all(p).unwrap();}
